css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; animation: cups calc(var(--loader-speed) * 1.2) linear infinite; }
.loader::after { content: ''; position: absolute; top: 44%; left: 44%; width: 12%; height: 12%; border-radius: 50%; background: color-mix(in srgb, #000 30%, var(--accent-2)); }
.loader span { position: absolute; top: 50%; left: 50%; width: 40%; height: 7%; margin-top: -3.5%; border-radius: 999px; transform-origin: left center; background: var(--accent-2); }
.loader span::after { content: ''; position: absolute; right: -16%; top: -170%; width: 42%; height: 440%; border-radius: 0 999px 999px 0; background: linear-gradient(90deg, color-mix(in srgb, #000 18%, var(--accent)), var(--accent)); }
.loader span:nth-child(2) { transform: rotate(120deg); }
.loader span:nth-child(3) { transform: rotate(240deg); }
@keyframes cups { to { transform: rotate(360deg); } }
